import java.util.*;

public class Avant21 {
    public static void main(String[] args) {
        // 1) Sur une List : get(0) et get(size - 1).
        List<String> liste = new ArrayList<>(List.of("a", "b", "c"));
        String premierListe = liste.get(0);
        String dernierListe = liste.get(liste.size() - 1);

        // 2) Sur une Deque : getFirst() et getLast().
        Deque<String> deque = new ArrayDeque<>(List.of("a", "b", "c"));
        String premierDeque = deque.getFirst();
        String dernierDeque = deque.getLast();

        // 3) Sur un LinkedHashSet : AUCUNE methode directe avant 21.
        LinkedHashSet<String> set = new LinkedHashSet<>(List.of("a", "b", "c"));
        String premierSet = set.iterator().next(); // bricolage pour le premier
        String dernierSet = null;
        for (String s : set) {                      // bricolage pour le dernier
            dernierSet = s;
        }
    }
}

import java.util.*;

public class Apres21 {
    public static void main(String[] args) {
        List<String> liste = new ArrayList<>(List.of("a", "b", "c"));

        // Fini get(0) et get(size - 1) : on dit ce qu'on veut.
        System.out.println(liste.getFirst()); // a
        System.out.println(liste.getLast());  // c

        // On ajoute aux deux bouts sans calcul d'indice.
        liste.addFirst("debut");
        liste.addLast("fin");
        System.out.println(liste); // [debut, a, b, c, fin]

        // On retire aux deux bouts ; la methode renvoie l'element retire.
        String enleveDebut = liste.removeFirst(); // "debut"
        String enleveFin = liste.removeLast();     // "fin"
        System.out.println(liste); // [a, b, c]
    }
}

