import java.util.*;

public class Inverse {
    public static void main(String[] args) {
        List<String> liste = new ArrayList<>(List.of("a", "b", "c"));

        // reversed() donne une vue dans l'ordre inverse.
        List<String> alEnvers = liste.reversed();
        System.out.println(alEnvers); // [c, b, a]

        // Parcourir a l'envers devient trivial : plus de boucle descendante.
        for (String s : liste.reversed()) {
            System.out.println(s); // c, puis b, puis a
        }

        // Sur la vue inversee, getFirst() est le dernier de l'originale.
        System.out.println(liste.reversed().getFirst()); // c
    }
}

import java.util.*;

public class VueBranchee {
    public static void main(String[] args) {
        List<String> liste = new ArrayList<>(List.of("a", "b", "c"));
        List<String> vue = liste.reversed();

        // addFirst sur la vue = ajouter a la FIN de l'originale.
        vue.addFirst("z");
        System.out.println(liste); // [a, b, c, z]
        System.out.println(vue);   // [z, c, b, a]

        // Un changement sur l'originale se voit aussitot dans la vue.
        liste.addFirst("debut");
        System.out.println(vue);   // [z, c, b, a, debut]
    }
}

import java.util.*;

public class SetSequence {
    public static void main(String[] args) {
        LinkedHashSet<String> invites = new LinkedHashSet<>();
        invites.add("Ana");
        invites.add("Bob");
        invites.add("Cléa");

        // Enfin des methodes directes, comme pour une List.
        System.out.println(invites.getFirst()); // Ana
        System.out.println(invites.getLast());   // Cléa

        // La vue inversee marche aussi.
        System.out.println(invites.reversed());   // [Cléa, Bob, Ana]

        // Ajouter au debut est possible (l'ordre est respecte).
        invites.addFirst("Zoé");
        System.out.println(invites); // [Zoé, Ana, Bob, Cléa]
    }
}

import java.util.*;

public class MapSequence {
    public static void main(String[] args) {
        LinkedHashMap<String, Integer> scores = new LinkedHashMap<>();
        scores.put("Ana", 10);
        scores.put("Bob", 7);
        scores.put("Cléa", 9);

        // Premiere et derniere entree (la paire cle=valeur).
        System.out.println(scores.firstEntry()); // Ana=10
        System.out.println(scores.lastEntry());   // Cléa=9

        // Les cles dans l'ordre, sous forme de vue.
        System.out.println(scores.sequencedKeySet()); // [Ana, Bob, Cléa]

        // Retirer la premiere entree et la recuperer.
        var premiere = scores.pollFirstEntry();
        System.out.println(premiere); // Ana=10
        System.out.println(scores);   // {Bob=7, Cléa=9}

        // Inserer une paire tout au debut.
        scores.putFirst("Zoé", 12);
        System.out.println(scores);   // {Zoé=12, Bob=7, Cléa=9}
    }
}

import java.util.*;

public class AvantApres {
    // AVANT : indices et formule a risque.
    static String dernierMessageAvant(List<String> messages) {
        if (messages.isEmpty()) return "aucun";
        return messages.get(messages.size() - 1);
    }

    // APRES : on dit simplement ce qu'on veut.
    static String dernierMessageApres(List<String> messages) {
        if (messages.isEmpty()) return "aucun";
        return messages.getLast();
    }

    // AVANT : boucle descendante pour l'ordre inverse.
    static void afficherEnversAvant(List<String> messages) {
        for (int i = messages.size() - 1; i >= 0; i--) {
            System.out.println(messages.get(i));
        }
    }

    // APRES : une vue inversee, lisible d'un coup d'oeil.
    static void afficherEnversApres(List<String> messages) {
        for (String m : messages.reversed()) {
            System.out.println(m);
        }
    }
}

import java.util.*;

public class Historique {
    public static void main(String[] args) {
        LinkedHashSet<String> pages = new LinkedHashSet<>();
        pages.addLast("accueil");
        pages.addLast("profil");
        pages.addLast("parametres");

        // La page la plus recente.
        System.out.println("Derniere page : " + pages.getLast()); // parametres

        // De la plus recente a la plus ancienne.
        System.out.println("Historique recent :");
        for (String page : pages.reversed()) {
            System.out.println(" - " + page); // parametres, profil, accueil
        }
    }
}

